#### Program.cs Registration

```csharp
using MassTransit;
using Amazon.GlueSchemaRegistry;
using Polly;
using StackExchange.Redis;

var builder = WebApplication.CreateBuilder(args);

// Register Redis for deduplication
builder.Services.AddSingleton<IConnectionMultiplexer>(sp =>
{
    var config = builder.Configuration.GetValue<string>("Deduplication:RedisConnectionString");
    return ConnectionMultiplexer.Connect(config);
});

// Register AWS Glue Schema Registry
builder.Services.AddSingleton<IAWSGlueSchemaRegistry>(sp =>
{
    var endpoint = builder.Configuration.GetValue<string>("SchemaRegistry:Endpoint");
    var region = builder.Configuration.GetValue<string>("SchemaRegistry:Region");
    return new AWSGlueSchemaRegistry(endpoint, region);
});

// Register Circuit Breaker
builder.Services.AddSingleton<IAsyncPolicy>(sp =>
{
    var failureThreshold = builder.Configuration.GetValue<int>("CircuitBreaker:FailureThreshold");
    var samplingDuration = TimeSpan.FromSeconds(
        builder.Configuration.GetValue<int>("CircuitBreaker:SamplingDurationSeconds"));
    var breakDuration = TimeSpan.FromSeconds(
        builder.Configuration.GetValue<int>("CircuitBreaker:BreakDurationSeconds"));

    return Policy
        .Handle<Exception>()
        .AdvancedCircuitBreakerAsync(
            failureThreshold: 0.5, // 50% failure rate
            samplingDuration: samplingDuration,
            minimumThroughput: builder.Configuration.GetValue<int>("CircuitBreaker:MinimumThroughput"),
            durationOfBreak: breakDuration,
            onBreak: (exception, duration) =>
            {
                Log.Warning("Circuit breaker opened for {Duration}ms", duration.TotalMilliseconds);
            },
            onReset: () => Log.Information("Circuit breaker reset"),
            onHalfOpen: () => Log.Information("Circuit breaker half-open"));
});

// Register AutoMapper
builder.Services.AddAutoMapper(typeof(Program).Assembly);

// Register FluentValidation
builder.Services.AddValidatorsFromAssemblyContaining<Program>();

// Register MassTransit
builder.Services.AddMassTransit(x =>
{
    var transport = builder.Configuration.GetValue<string>("MassTransit:Transport");

    // Register consumers
    x.AddConsumer<ExternalClaimReceivedConsumer>();
    x.AddConsumer<ExternalPaymentProcessedConsumer>();

    // Configure transport
    switch (transport)
    {
        case "Kafka":
            x.UsingInMemory((context, cfg) => cfg.ConfigureEndpoints(context));
            x.AddRider(rider =>
            {
                rider.AddConsumer<ExternalClaimReceivedConsumer>();

                rider.UsingKafka((context, k) =>
                {
                    var kafkaConfig = builder.Configuration.GetSection("MassTransit:Kafka");

                    k.Host(kafkaConfig.GetValue<string>("BootstrapServers"), h =>
                    {
                        h.UseSasl(sasl =>
                        {
                            sasl.SecurityProtocol = Confluent.Kafka.SecurityProtocol.SaslSsl;
                            sasl.Mechanism = Confluent.Kafka.SaslMechanism.Plain;
                            sasl.Username = kafkaConfig.GetValue<string>("SaslUsername");
                            sasl.Password = kafkaConfig.GetValue<string>("SaslPassword");
                        });
                    });

                    k.TopicEndpoint<ExternalClaimReceivedEvent>("external.claims.received.v1",
                        kafkaConfig.GetValue<string>("GroupId"), e =>
                    {
                        e.ConfigureConsumer<ExternalClaimReceivedConsumer>(context);

                        e.AutoOffsetReset = Confluent.Kafka.AutoOffsetReset.Earliest;
                        e.EnableAutoCommit = false;

                        // Configure retry policy
                        e.UseMessageRetry(r => r.Exponential(
                            retryLimit: 3,
                            minInterval: TimeSpan.FromSeconds(1),
                            maxInterval: TimeSpan.FromSeconds(30),
                            intervalDelta: TimeSpan.FromSeconds(2)));

                        // Configure error handling
                        e.UseInlineFilter((context, next) =>
                        {
                            try
                            {
                                return next.Send(context);
                            }
                            catch (Exception ex)
                            {
                                // Log and move to DLQ
                                Log.Error(ex, "Consumer error for message {MessageId}",
                                    context.MessageId);
                                throw;
                            }
                        });
                    });
                });
            });
            break;

        case "RabbitMQ":
            x.UsingRabbitMq((context, cfg) =>
            {
                var rmqConfig = builder.Configuration.GetSection("MassTransit:RabbitMQ");

                cfg.Host(rmqConfig.GetValue<string>("Host"), h =>
                {
                    h.Username(rmqConfig.GetValue<string>("Username"));
                    h.Password(rmqConfig.GetValue<string>("Password"));
                    if (rmqConfig.GetValue<bool>("UseSsl"))
                    {
                        h.UseSsl(s => s.Protocol = System.Security.Authentication.SslProtocols.Tls12);
                    }
                });

                cfg.PrefetchCount = rmqConfig.GetValue<ushort>("PrefetchCount");
                cfg.ConfigureEndpoints(context);
            });
            break;

        case "Redis":
            x.UsingInMemory((context, cfg) => cfg.ConfigureEndpoints(context));
            x.AddRider(rider =>
            {
                rider.AddConsumer<ExternalClaimReceivedConsumer>();

                rider.UsingRedis((context, r) =>
                {
                    var redisConfig = builder.Configuration.GetSection("MassTransit:Redis");
                    r.Host(redisConfig.GetValue<string>("Configuration"));

                    r.StreamEndpoint<ExternalClaimReceivedEvent>("external-claims-stream", e =>
                    {
                        e.ConfigureConsumer<ExternalClaimReceivedConsumer>(context);
                    });
                });
            });
            break;
    }
});

var app = builder.Build();
app.Run();
