```csharp
// Services/SchemaValidationService.cs
using Amazon.GlueSchemaRegistry;
using Amazon.GlueSchemaRegistry.Model;

public class SchemaValidationService
{
    private readonly IAWSGlueSchemaRegistry _schemaRegistry;
    private readonly IMemoryCache _cache;
    private readonly ILogger<SchemaValidationService> _logger;

    public SchemaValidationService(
        IAWSGlueSchemaRegistry schemaRegistry,
        IMemoryCache cache,
        ILogger<SchemaValidationService> logger)
    {
        _schemaRegistry = schemaRegistry;
        _cache = cache;
        _logger = logger;
    }

    public async Task<ValidationResult> ValidateAsync<T>(
        T message,
        string schemaName,
        CancellationToken cancellationToken = default)
    {
        try
        {
            // Get schema from cache or registry
            var schema = await GetSchemaAsync(schemaName, cancellationToken);

            // Validate message against schema
            var json = JsonSerializer.Serialize(message);
            var isValid = ValidateJsonAgainstSchema(json, schema);

            if (!isValid)
            {
                _logger.LogWarning(
                    "Schema validation failed for {SchemaName}: {Json}",
                    schemaName, json);

                return ValidationResult.Failure($"Message does not conform to schema {schemaName}");
            }

            return ValidationResult.Success();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Schema validation error for {SchemaName}", schemaName);
            return ValidationResult.Failure($"Schema validation error: {ex.Message}");
        }
    }

    private async Task<string> GetSchemaAsync(string schemaName, CancellationToken cancellationToken)
    {
        var cacheKey = $"schema:{schemaName}";

        if (_cache.TryGetValue(cacheKey, out string cachedSchema))
        {
            return cachedSchema;
        }

        var response = await _schemaRegistry.GetSchemaByDefinitionAsync(
            new GetSchemaByDefinitionRequest
            {
                SchemaId = new SchemaId { SchemaName = schemaName },
                SchemaDefinition = "" // Get latest
            },
            cancellationToken);

        var schema = response.SchemaDefinition;

        _cache.Set(cacheKey, schema, TimeSpan.FromHours(1));

        return schema;
    }

    private bool ValidateJsonAgainstSchema(string json, string schema)
    {
        // Implementation depends on schema format (JSON Schema, Avro, etc.)
        // This is a simplified example
        try
        {
            var schemaObj = JsonSchema.FromJsonAsync(schema).Result;
            var messageObj = JsonDocument.Parse(json);
            var errors = schemaObj.Validate(messageObj);
            return !errors.Any();
        }
        catch
        {
            return false;
        }
    }
}
