### Idempotency Configuration

```csharp
// Services/IdempotencyService.cs
using StackExchange.Redis;

public class IdempotencyService
{
    private readonly IConnectionMultiplexer _redis;
    private readonly ILogger<IdempotencyService> _logger;
    private readonly string _keyPrefix;
    private readonly TimeSpan _ttl;

    public IdempotencyService(
        IConnectionMultiplexer redis,
        IConfiguration configuration,
        ILogger<IdempotencyService> logger)
    {
        _redis = redis;
        _logger = logger;
        _keyPrefix = configuration.GetValue<string>("Deduplication:KeyPrefix");
        _ttl = TimeSpan.FromHours(configuration.GetValue<int>("Deduplication:TtlHours"));
    }

    public async Task<bool> IsProcessedAsync(
        string messageId,
        string sourceSystem,
        string correlationId,
        CancellationToken cancellationToken = default)
    {
        var key = GenerateKey(messageId, sourceSystem, correlationId);
        var db = _redis.GetDatabase();

        var exists = await db.KeyExistsAsync(key);

        if (exists)
        {
            _logger.LogInformation(
                "Duplicate message detected: {MessageId} from {SourceSystem}",
                messageId, sourceSystem);
        }

        return exists;
    }

    public async Task MarkAsProcessedAsync(
        string messageId,
        string sourceSystem,
        string correlationId,
        CancellationToken cancellationToken = default)
    {
        var key = GenerateKey(messageId, sourceSystem, correlationId);
        var db = _redis.GetDatabase();

        await db.StringSetAsync(key, DateTime.UtcNow.ToString("O"), _ttl);

        _logger.LogDebug(
            "Marked message as processed: {MessageId} from {SourceSystem}",
            messageId, sourceSystem);
    }

    private string GenerateKey(string messageId, string sourceSystem, string correlationId)
    {
        return $"{_keyPrefix}{sourceSystem}:{correlationId}:{messageId}";
    }
}
