// Mappings/IntegrationEventMappingProfile.cs
using AutoMapper;
using ClaimsIntegrationConsumer.Events;
using ClaimsIntegrationConsumer.Domain;

public class IntegrationEventMappingProfile : Profile
{
    public IntegrationEventMappingProfile()
    {
        CreateMap<ExternalClaimReceivedEvent, Claim>()
            .ForMember(dest => dest.Id, opt => opt.MapFrom(src => Guid.NewGuid()))
            .ForMember(dest => dest.ExternalClaimId, opt => opt.MapFrom(src => src.ClaimId))
            .ForMember(dest => dest.ExternalSystemId, opt => opt.MapFrom(src => src.ExternalSystemId))
            .ForMember(dest => dest.MemberId, opt => opt.MapFrom(src => ParseGuid(src.MemberId)))
            .ForMember(dest => dest.ProviderId, opt => opt.MapFrom(src => ParseGuid(src.ProviderId)))
            .ForMember(dest => dest.Amount, opt => opt.MapFrom(src => src.ClaimAmount))
            .ForMember(dest => dest.ServiceDate, opt => opt.MapFrom(src => src.ServiceDate))
            .ForMember(dest => dest.ReceivedDate, opt => opt.MapFrom(src => src.ReceivedDate))
            .ForMember(dest => dest.Status, opt => opt.MapFrom(src => ClaimStatus.Received))
            .ForMember(dest => dest.CreatedAt, opt => opt.MapFrom(src => DateTime.UtcNow))
            .ForMember(dest => dest.CreatedBy, opt => opt.MapFrom(src => "IntegrationConsumer"));
    }

    private static Guid ParseGuid(string value)
    {
        return Guid.TryParse(value, out var guid) ? guid : Guid.Empty;
    }
}
