// Validators/ClaimValidator.cs
using FluentValidation;
using ClaimsIntegrationConsumer.Domain;

public class ClaimValidator : AbstractValidator<Claim>
{
    public ClaimValidator()
    {
        RuleFor(x => x.ExternalClaimId)
            .NotEmpty()
            .WithMessage("External claim ID is required");

        RuleFor(x => x.MemberId)
            .NotEqual(Guid.Empty)
            .WithMessage("Valid member ID is required");

        RuleFor(x => x.ProviderId)
            .NotEqual(Guid.Empty)
            .WithMessage("Valid provider ID is required");

        RuleFor(x => x.Amount)
            .GreaterThan(0)
            .WithMessage("Claim amount must be greater than zero");

        RuleFor(x => x.ServiceDate)
            .LessThanOrEqualTo(DateTime.UtcNow)
            .WithMessage("Service date cannot be in the future");
    }
}
