#### Step 4.1: Create Consumer

```csharp
// Consumers/ExternalClaimReceivedConsumer.cs
using MassTransit;
using AutoMapper;
using FluentValidation;
using Polly;
using ClaimsIntegrationConsumer.Events;
using ClaimsIntegrationConsumer.Domain;
using ClaimsIntegrationConsumer.Services;

public class ExternalClaimReceivedConsumer : IConsumer<ExternalClaimReceivedEvent>
{
    private readonly IMapper _mapper;
    private readonly IValidator<Claim> _validator;
    private readonly SchemaValidationService _schemaValidator;
    private readonly IdempotencyService _idempotencyService;
    private readonly IAsyncPolicy _circuitBreaker;
    private readonly IClaimRepository _claimRepository;
    private readonly ILogger<ExternalClaimReceivedConsumer> _logger;

    public ExternalClaimReceivedConsumer(
        IMapper mapper,
        IValidator<Claim> validator,
        SchemaValidationService schemaValidator,
        IdempotencyService idempotencyService,
        IAsyncPolicy circuitBreaker,
        IClaimRepository claimRepository,
        ILogger<ExternalClaimReceivedConsumer> logger)
    {
        _mapper = mapper;
        _validator = validator;
        _schemaValidator = schemaValidator;
        _idempotencyService = idempotencyService;
        _circuitBreaker = circuitBreaker;
        _claimRepository = claimRepository;
        _logger = logger;
    }

    public async Task Consume(ConsumeContext<ExternalClaimReceivedEvent> context)
    {
        var @event = context.Message;
        var correlationId = @event.CorrelationId;

        using var activity = Activity.Current?.Source.StartActivity(
            "ConsumeExternalClaimReceived",
            ActivityKind.Consumer);

        activity?.SetTag("external.system", @event.ExternalSystemId);
        activity?.SetTag("claim.id", @event.ClaimId);
        activity?.SetTag("correlation.id", correlationId);

        try
        {
            _logger.LogInformation(
                "Processing external claim {ClaimId} from {SystemId} with correlation {CorrelationId}",
                @event.ClaimId, @event.ExternalSystemId, correlationId);

            // REQ-INT-001-005: Check idempotency
            var isDuplicate = await _idempotencyService.IsProcessedAsync(
                @event.ClaimId,
                @event.ExternalSystemId,
                correlationId,
                context.CancellationToken);

            if (isDuplicate)
            {
                _logger.LogInformation(
                    "Duplicate claim detected: {ClaimId} from {SystemId}",
                    @event.ClaimId, @event.ExternalSystemId);
                return; // Successfully handled duplicate
            }

            // REQ-INT-001-002: Validate against schema
            var schemaValidation = await _schemaValidator.ValidateAsync(
                @event,
                "external-claims.received.v1",
                context.CancellationToken);

            if (!schemaValidation.IsValid)
            {
                _logger.LogError(
                    "Schema validation failed for claim {ClaimId}: {Errors}",
                    @event.ClaimId, schemaValidation.ErrorMessage);

                // Route to DLQ
                throw new SchemaValidationException(schemaValidation.ErrorMessage);
            }

            // REQ-INT-001-008: Map external event to domain model
            var claim = _mapper.Map<Claim>(@event);

            // Validate mapped domain object
            var validationResult = await _validator.ValidateAsync(claim, context.CancellationToken);
            if (!validationResult.IsValid)
            {
                _logger.LogError(
                    "Domain validation failed for claim {ClaimId}: {Errors}",
                    @event.ClaimId,
                    string.Join(", ", validationResult.Errors.Select(e => e.ErrorMessage)));

                throw new DomainValidationException(
                    $"Domain validation failed: {string.Join(", ", validationResult.Errors.Select(e => e.ErrorMessage))}");
            }

            // REQ-INT-001-003: Process with circuit breaker protection
            await _circuitBreaker.ExecuteAsync(async () =>
            {
                await _claimRepository.SaveAsync(claim, context.CancellationToken);

                _logger.LogInformation(
                    "Successfully saved claim {ClaimId} with internal ID {InternalId}",
                    @event.ClaimId, claim.Id);
            });

            // REQ-INT-001-005: Mark as processed for idempotency
            await _idempotencyService.MarkAsProcessedAsync(
                @event.ClaimId,
                @event.ExternalSystemId,
                correlationId,
                context.CancellationToken);

            _logger.LogInformation(
                "Successfully processed external claim {ClaimId} from {SystemId}",
                @event.ClaimId, @event.ExternalSystemId);
        }
        catch (SchemaValidationException ex)
        {
            _logger.LogError(ex,
                "Schema validation error for claim {ClaimId} from {SystemId}",
                @event.ClaimId, @event.ExternalSystemId);

            // REQ-INT-001-004: Route to DLQ with metadata
            throw; // MassTransit will handle DLQ routing
        }
        catch (DomainValidationException ex)
        {
            _logger.LogError(ex,
                "Domain validation error for claim {ClaimId} from {SystemId}",
                @event.ClaimId, @event.ExternalSystemId);

            throw; // Route to DLQ
        }
        catch (BrokenCircuitException ex)
        {
            _logger.LogError(ex,
                "Circuit breaker open - cannot process claim {ClaimId}",
                @event.ClaimId);

            // Don't route to DLQ; let Kafka redelivery handle it
            throw;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                "Unexpected error processing claim {ClaimId} from {SystemId}",
                @event.ClaimId, @event.ExternalSystemId);

            throw; // Route to DLQ after retries exhausted
        }
    }
}

public class SchemaValidationException : Exception
{
    public SchemaValidationException(string message) : base(message) { }
}

public class DomainValidationException : Exception
{
    public DomainValidationException(string message) : base(message) { }
}
```

